set -euo pipefail
project_dir="$(cd -- "$(dirname -- "${BASH_SOURCE[0]}")/.." && pwd)"; root="$(mktemp -d /tmp/devario-final-approval-test.XXXXXX)"; trap 'rm -rf -- "$root"' EXIT; mkdir "$root/evidence" "$root/bin"
fingerprint=1111111111111111111111111111111111111111
jq -n '{schemaVersion:2,edition:"community",version:"test",architecture:"x86_64",candidateChannel:"devario-core-testing",coreCommit:("a"*40),overlayCommit:null,sourceDateEpoch:1786579200,createdAt:"2026-08-13T00:00:00Z",artifacts:[{path:"devario.iso",sha256:("1"*64),size:1,mode:"644"}],artifactSetSha256:("2"*64),metadata:[{path:"release.json",sha256:("3"*64),size:1,mode:"644"}],metadataSetSha256:("4"*64),buildEvidence:{coreInputLock:{name:"CORE-INPUT-LOCK.json",sha256:("5"*64)},overlayInputLock:null,builderManifest:{name:"CONTROLLED-BUILDER.json",sha256:("1"*64)},builderManifestSignature:{name:"CONTROLLED-BUILDER.json.sig",sha256:("2"*64)},builderAttestation:{name:"BUILDER-ATTESTATION.json",sha256:("6"*64)},builderAttestationSignature:{name:"BUILDER-ATTESTATION.json.sig",sha256:("3"*64)}}}' > "$root/candidate.json"
jq -n '{schemaVersion:1,outcome:"pass",subjectSetSha256:("7"*64),subjectIdentitySha256:("8"*64),comparedSubjects:1,builds:[{releaseMetadataSha256:("9"*64),candidateLockSha256:("a"*64),artifactSetSha256:("2"*64),builderId:"https://builder.example/one",invocationId:"independent-one",coreInputLockSha256:("5"*64),overlayInputLockSha256:null},{releaseMetadataSha256:("b"*64),candidateLockSha256:("c"*64),artifactSetSha256:("2"*64),builderId:"https://builder.example/two",invocationId:"independent-two",coreInputLockSha256:("5"*64),overlayInputLockSha256:null}],excludedPerRunMetadata:["provenance.intoto.json:predicate.runDetails"]}' > "$root/reproducibility.json"
candidate_sha="$(sha256sum "$root/candidate.json" | cut -d' ' -f1)"
jq -n --arg candidate "$candidate_sha" '{schemaVersion:2,candidateSha256:$candidate,candidateVersion:"test",edition:"community",diskFormat:"raw",installedDisk:{path:"installed.raw",sha256:("1"*64),size:1},installationLock:{path:"installation-lock.json",sha256:("2"*64),size:1},installationReview:{document:{path:"installation-review.json",sha256:("3"*64),size:1},signature:{path:"installation-review.json.sig",sha256:("4"*64),size:1}},results:[{mode:"live",firmware:"bios",document:{path:"live-bios.json",sha256:("5"*64),size:1},log:{path:"live-bios.log",sha256:("6"*64),size:1}},{mode:"live",firmware:"uefi",document:{path:"live-uefi.json",sha256:("7"*64),size:1},log:{path:"live-uefi.log",sha256:("8"*64),size:1}},{mode:"installed",firmware:"uefi",document:{path:"installed-uefi.json",sha256:("b"*64),size:1},log:{path:"installed-uefi.log",sha256:("c"*64),size:1}}]}' > "$root/evidence/promotion-acceptance.json"
printf 'canonical evidence manifest\n' > "$root/evidence/ACCEPTANCE.SHA256SUMS"
jq '.candidateVersion="other"' "$root/evidence/promotion-acceptance.json" > "$root/evidence/wrong-version-acceptance.json"
if DEVARIO_APPROVED_AT=2026-08-13T02:00:00Z "$project_dir/release/generate-final-approval.sh" --candidate "$root/candidate.json" --reproducibility "$root/reproducibility.json" --acceptance-manifest "$root/evidence/wrong-version-acceptance.json" --target-channel devario-core-stable --approver-fingerprint "$fingerprint" --output "$root/wrong-version-approval.json" >/dev/null 2>&1; then
  echo 'Final approval accepted evidence for a different candidate version.' >&2; exit 1
fi
DEVARIO_APPROVED_AT=2026-08-13T02:00:00Z "$project_dir/release/generate-final-approval.sh" --candidate "$root/candidate.json" --reproducibility "$root/reproducibility.json" --acceptance-manifest "$root/evidence/promotion-acceptance.json" --target-channel devario-core-stable --approver-fingerprint "$fingerprint" --output "$root/approval.json" >/dev/null
printf 'signature\n' > "$root/approval.json.sig"; printf 'keyring\n' > "$root/approvers.gpg"
jq -n --arg fingerprint "$fingerprint" '{"$schema":"./trust-policy.schema.json",schemaVersion:1,purpose:"human-release-approval",activeFingerprint:$fingerprint,approvedFingerprints:[$fingerprint],forbiddenFingerprints:["580E40BB6D6E8745D69D89CC6E6C90512593874C","E199A52D6C3B80057E08C7BB645354F2E56FEC5D"]}' > "$root/trust.json"
printf '%s\n' '#!/usr/bin/env bash' 'printf "[GNUPG:] VALIDSIG 1111111111111111111111111111111111111111 2026-08-13 1786579200 0 4 0 22 8 00 1111111111111111111111111111111111111111\n"' > "$root/bin/gpgv"; chmod 0755 "$root/bin/gpgv"
printf '%s\n' '#!/usr/bin/env bash' 'printf "pub:::::::::\nfpr:::::::::1111111111111111111111111111111111111111:\n"' > "$root/bin/gpg"; chmod 0755 "$root/bin/gpg"
PATH="$root/bin:$PATH" "$project_dir/release/validate-final-approval.sh" --approval "$root/approval.json" --signature "$root/approval.json.sig" --candidate "$root/candidate.json" --reproducibility "$root/reproducibility.json" --acceptance-manifest "$root/evidence/promotion-acceptance.json" --target-channel devario-core-stable --trust-policy "$root/trust.json" --keyring "$root/approvers.gpg" >/dev/null
if PATH="$root/bin:$PATH" "$project_dir/release/validate-final-approval.sh" --approval "$root/approval.json" --signature "$root/approval.json.sig" --candidate "$root/candidate.json" --reproducibility "$root/reproducibility.json" --acceptance-manifest "$root/evidence/promotion-acceptance.json" --target-channel attacker-stable --trust-policy "$root/trust.json" --keyring "$root/approvers.gpg" >/dev/null 2>&1; then echo 'Final approval accepted a different target channel.' >&2; exit 1; fi
printf '{"managed":true}\n' > "$root/managed-lock.json"
if DEVARIO_APPROVED_AT=2026-08-13T02:00:00Z "$project_dir/release/generate-final-approval.sh" --candidate "$root/candidate.json" --reproducibility "$root/reproducibility.json" --acceptance-manifest "$root/evidence/promotion-acceptance.json" --edition-evidence "$root/managed-lock.json" --target-channel devario-core-stable --approver-fingerprint "$fingerprint" --output "$root/community-with-managed-evidence.json" >/dev/null 2>&1; then
  echo 'Community final approval accepted Managed edition evidence.' >&2; exit 1
fi

jq '.edition="managed" | .candidateChannel="devario-managed-pilot" | .overlayCommit=("b"*40) | .buildEvidence.overlayInputLock={name:"MANAGED-INPUT-LOCK.json",sha256:("d"*64)}' "$root/candidate.json" > "$root/managed-candidate.json"
managed_candidate_sha="$(sha256sum "$root/managed-candidate.json" | cut -d' ' -f1)"
jq --arg candidate "$managed_candidate_sha" '.candidateSha256=$candidate | .edition="managed"' "$root/evidence/promotion-acceptance.json" > "$root/evidence/managed-acceptance.json"
jq '.builds |= map(.overlayInputLockSha256=("d"*64))' "$root/reproducibility.json" > "$root/managed-reproducibility.json"
if DEVARIO_APPROVED_AT=2026-08-13T02:00:00Z "$project_dir/release/generate-final-approval.sh" --candidate "$root/managed-candidate.json" --reproducibility "$root/managed-reproducibility.json" --acceptance-manifest "$root/evidence/managed-acceptance.json" --target-channel devario-managed-stable --approver-fingerprint "$fingerprint" --output "$root/managed-without-evidence.json" >/dev/null 2>&1; then
  echo 'Managed final approval omitted edition evidence.' >&2; exit 1
fi
DEVARIO_APPROVED_AT=2026-08-13T02:00:00Z "$project_dir/release/generate-final-approval.sh" --candidate "$root/managed-candidate.json" --reproducibility "$root/managed-reproducibility.json" --acceptance-manifest "$root/evidence/managed-acceptance.json" --edition-evidence "$root/managed-lock.json" --target-channel devario-managed-stable --approver-fingerprint "$fingerprint" --output "$root/managed-approval.json" >/dev/null
printf 'signature\n' > "$root/managed-approval.json.sig"
PATH="$root/bin:$PATH" "$project_dir/release/validate-final-approval.sh" --approval "$root/managed-approval.json" --signature "$root/managed-approval.json.sig" --candidate "$root/managed-candidate.json" --reproducibility "$root/managed-reproducibility.json" --acceptance-manifest "$root/evidence/managed-acceptance.json" --edition-evidence "$root/managed-lock.json" --target-channel devario-managed-stable --trust-policy "$root/trust.json" --keyring "$root/approvers.gpg" >/dev/null
mkdir "$root/changed"; printf '{"managed":"changed"}\n' > "$root/changed/managed-lock.json"
if PATH="$root/bin:$PATH" "$project_dir/release/validate-final-approval.sh" --approval "$root/managed-approval.json" --signature "$root/managed-approval.json.sig" --candidate "$root/managed-candidate.json" --reproducibility "$root/managed-reproducibility.json" --acceptance-manifest "$root/evidence/managed-acceptance.json" --edition-evidence "$root/changed/managed-lock.json" --target-channel devario-managed-stable --trust-policy "$root/trust.json" --keyring "$root/approvers.gpg" >/dev/null 2>&1; then
  echo 'Managed final approval accepted changed edition evidence.' >&2; exit 1
fi
managed_dev=580E40BB6D6E8745D69D89CC6E6C90512593874C
jq -n --arg fingerprint "$managed_dev" '{"$schema":"./trust-policy.schema.json",schemaVersion:1,purpose:"human-release-approval",activeFingerprint:$fingerprint,approvedFingerprints:[$fingerprint],forbiddenFingerprints:[$fingerprint,"E199A52D6C3B80057E08C7BB645354F2E56FEC5D"]}' > "$root/forbidden-trust.json"
if PATH="$root/bin:$PATH" "$project_dir/release/validate-trust-policy.sh" --policy "$root/forbidden-trust.json" --keyring "$root/approvers.gpg" --purpose human-release-approval >/dev/null 2>&1; then echo 'Human approval trust accepted the Managed development signer.' >&2; exit 1; fi
echo 'Final approval tests passed.'
